"""Writes tests/fixtures/*.html. Markup and text are copied from armnab.am (November 2026);
long scope lists are shortened to keep the files small."""
from pathlib import Path

OUT = Path(__file__).parent / "fixtures"
SHELL = '<!DOCTYPE html><html lang="hy"><head><meta charset="utf-8"><title>{title}</title></head><body><main>{main}</main></body></html>'

def row(label, value):
    return f'<div class="dlist__row"><dt>{label}</dt><dd>{value}</dd></div>'

def full(label, lines):
    text = "\n                ".join(lines)
    head = f'<div class="dlist__row"><dt>{label}</dt></div>' if label else ""
    return f'{head}<div class="dlist__row__full__width"><dd>{text}</dd></div>'

def block(title, body):
    return f'<section class="detail-block"><h2 class="detail-block__title">{title}</h2><dl class="dlist">{body}</dl></section>'

def detail(status, css, name, reg, start, end, phone, email, legal, activity, scope, extra=""):
    general = "".join([row("Հավատարմագրման վկայագրի գրանցման համարը", reg), row("Գործողության ժամկետը սկսած", start),
                       row("Մինչև ներառյալ", end), row("Որոշման համարը", "N 24/1"), row("Որոշման ամսաթիվը", start),
                       row("Ձևաթղթի համարը", "000825")])
    body = "".join([row("Անվանումը (լրիվ)", name), row("Ղեկավար", "Աննա Ղազարյան"), row("Հեռախոս", phone), row("Ֆաքս", "-"), row("Էլ․ հասցե", email)])
    address = row("Իրավաբանական անձի գտնվելու վայր", legal) + row("Գործունեության իրականացման վայր", activity)
    main = (f'<div class="detail"><div class="wrap detail__head"><span class="badge {css}">{status}</span><h1 class="detail__title">{name}</h1></div>'
            f'<div class="wrap detail__body">{block("Ընդհանուր տեղեկություններ", general)}{block("Մարմնի մասին տվյալներ", body)}{block("Հասցեներ", address)}'
            f'{block("Հավատարմագրման ոլորտը", full("Մանրամասն նկարագրությունը", scope))}{extra}<a class="btn-back" href="/management-systems">Վերադառնալ</a></div></div>')
    return SHELL.format(title=name, main=main)

